// frontend/src/components/Sidebar.jsx
import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import ProfileMenu from "./ProfileMenu";
import "./Sidebar.css";

export default function Sidebar({ sessions = [], onLoadSession = () => {}, onNewChat = () => {} }) {
  const [remoteSessions, setRemoteSessions] = useState([]);
  const [loadingDelete, setLoadingDelete] = useState(null); // id being deleted
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    fetch("/api/sessions/list")
      .then((r) => (r.ok ? r.json() : []))
      .then((data) => {
        if (Array.isArray(data)) setRemoteSessions(data);
      })
      .catch(() => setRemoteSessions([]));
  }, []);

  const mergedSessions = React.useMemo(() => {
    const map = new Map();
    (sessions || []).forEach((s) => {
      if (s && s.id) map.set(String(s.id), s);
    });
    (remoteSessions || []).forEach((rs) => {
      if (rs && rs.id && !map.has(String(rs.id))) map.set(String(rs.id), rs);
    });
    return Array.from(map.values()).slice(0, 50);
  }, [sessions, remoteSessions]);

  async function handleDeleteSession(id) {
    if (!id) return;
    if (!window.confirm("Delete this chat? This action cannot be undone.")) return;
    setLoadingDelete(id);
    try {
      const resp = await fetch(`/api/sessions/${encodeURIComponent(id)}`, { method: "DELETE" });
      if (!resp.ok) {
        const text = await resp.text();
        throw new Error(text || "Failed to delete session");
      }
      setRemoteSessions((rs) => rs.filter((r) => String(r.id) !== String(id)));
      try {
        const raw = localStorage.getItem("ai_chat_sessions");
        if (raw) {
          const arr = JSON.parse(raw).filter((x) => String(x.id) !== String(id));
          localStorage.setItem("ai_chat_sessions", JSON.stringify(arr));
        }
      } catch (e) { /* ignore */ }
    } catch (e) {
      console.error("Delete failed:", e);
      alert("Failed to delete session.");
    } finally {
      setLoadingDelete(null);
    }
  }

  function handleLoadSession(sess) {
    try { onLoadSession(sess); } catch (e) { console.error(e); }
    navigate("/");
  }

  function handleNewChat() {
    try { onNewChat(); } catch (e) { console.error(e); }
    navigate("/");
  }

  return (
    <aside className="sidebar-root" role="navigation" aria-label="Sidebar">
      <div className="sidebar-top">
        <button className="btn-new" onClick={handleNewChat} aria-label="Start a new chat">＋ New Chat</button>

        <div className="sidebar-section">
          <div className="sidebar-title">Chat History</div>

          <div className="session-list" aria-live="polite">
            {mergedSessions.length === 0 ? (
              <div className="empty">No saved chats yet</div>
            ) : (
              mergedSessions.slice(0, 30).map((s) => (
                <div key={s.id} className="session-row" title={s.title || "Open chat"}>
                  <button
                    className="session-body"
                    onClick={() => handleLoadSession(s)}
                    aria-label={`Open chat ${s.title || s.id}`}
                  >
                    <div className="session-title" title={s.title || ""}>
                      {s.title || `Trip ${new Date(s.createdAt || Date.now()).toLocaleString()}`}
                    </div>
                    <div className="session-sub">{s.prompt ? s.prompt.slice(0, 70) : ""}</div>
                  </button>

                  <div className="session-actions">
                    <button
                      className="btn-delete"
                      onClick={(e) => { e.stopPropagation(); handleDeleteSession(s.id); }}
                      disabled={loadingDelete === s.id}
                      aria-label="Delete chat"
                      title="Delete"
                    >
                      {loadingDelete === s.id ? "…" : "🗑"}
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="sidebar-section nav-section">
          <div className="sidebar-title">Navigation</div>

          <nav className="nav-list" aria-label="Main navigation">
            <Link to="/flights" className={`nav-link ${location.pathname === "/flights" ? "active" : ""}`}>
              <span className="nav-ico">✈️</span>
              <span className="nav-text">Flight Search</span>
            </Link>

            <Link to="/hotels" className={`nav-link ${location.pathname === "/hotels" ? "active" : ""}`}>
              <span className="nav-ico">🏨</span>
              <span className="nav-text">Hotels & Cuisines</span>
            </Link>

            <Link to="/news" className={`nav-link ${location.pathname === "/news" ? "active" : ""}`}>
              <span className="nav-ico">📰</span>
              <span className="nav-text">Travel News & Blogs</span>
            </Link>
          </nav>
        </div>
      </div>

      <div className="sidebar-bottom">
        <ProfileMenu />
      </div>
    </aside>
  );
}
